const LE_KO={'Year':'연도','Status':'개발 상태(0 · 1)','Adult Mortality':'성인 사망률','infant deaths':'유아 사망 수','Alcohol':'1인당 알코올 소비량','percentage expenditure':'건강에 대한 지출','Hepatitis B':'B형 간염 예방 접종률','Measles':'홍역 환자 수','BMI':'평균 체질량 지수','under-five deaths':'5세 미만 사망 수','Polio':'소아마비 예방 접종률','Total expenditure':'정부 보건 관련 지출','Diphtheria':'디프테리아 예방 접종률','HIV/AIDS':'HIV/AIDS 사망 수','GDP':'1인당 국내 총생산','Population':'국가 총 인구수','thinness  1-19 years':'1~19세 야윔 유병률','thinness 5-9 years':'5~9세 야윔 유병률','Income composition of resources':'소득(자원 소득에 대한 국가 개발 정도)','Schooling':'국가 교육 기간'};
const LE_SHORT={'Income composition of resources':'Income composition'};
const LE_KO2={'Income composition of resources':'소득'};
const sname=c=>LE_SHORT[c]||c;

