/* 01 셀 실행 흉내 (197~200쪽) */
(function(){
  const B=$('cellSim');
  const CELLS=[
    {t:'준비 · 데이터 불러오기와 전처리',c:`<span class="c"># (import는 생략)</span>
df = pd.read_csv('Life Expectancy Data.csv')
df = df.dropna()
df = df.replace({'Developing': 0, 'Developed': 1})
df.shape`},
    {t:'[5] ③ X와 y 정하기',c:`X = df.drop(['Life expectancy', 'Country'], axis=1)
y = df.loc[:, 'Life expectancy']`},
    {t:'[5] ③ 훈련 데이터와 테스트 데이터로 나누기',c:`from sklearn.model_selection import train_test_split
X_train, X_test, y_train, y_test = train_test_split(X, y, test_size = 0.2,
                                                    random_state = 96)`},
    {t:'[5] ④ 잘 나눠졌는지 확인',c:`X_train.shape, y_train.shape, X_test.shape, y_test.shape`},
    {t:'[6] 1 모델 생성하기',c:`from sklearn.linear_model import LinearRegression
linear_reg = LinearRegression()`},
    {t:'[6] 2 모델 학습하기',c:`lin_results = linear_reg.fit(X_train, y_train)`},
    {t:'[6] 3 가중치와 편향 확인하기',c:`w = lin_results.coef_
b = lin_results.intercept_
print(w)
print(b)`},
    {t:'[7] 1 결정 계수 확인하기',c:`from sklearn.metrics import r2_score
y_pred = lin_results.predict(X_test)
print('결정 계수(R^2) = ', r2_score(y_test, y_pred))`},
    {t:'[7] 2 테스트 데이터로 평가하기',c:`Y_prediction = y_pred.flatten()
for i in range(6):
    label = y_test.values[i]
    prediction = Y_prediction[i]
    print('실제 기대 수명: {:.3f}, 학습 후 예측 기대 수명: {:.3f}, 차이: {:.3f}'
          .format(label, prediction, label - prediction))`},
    {t:'[8] 교육 기간으로 회귀선 학습하기',c:`lin1 = LinearRegression()
lin1.fit(X_train['Schooling'].values.reshape(-1, 1), y_train.values.reshape(-1, 1))`},
  ];
  let st;
  const OK='<span class="ok">✓ 실행 완료</span> <span class="muted">(출력 없음)</span>';
  const ERR=(e,why)=>`<div class="le-err">${e}</div><div class="le-why">${why}</div>`;
  const OUT=s=>`<pre class="le-out">${s}</pre>`;
  const NE=(n,why)=>ERR(`NameError: name '${n}' is not defined`,why);
  function run(i){
    const o=st.out;
    if(i===0){ st.df=true; o[0]=OUT('(1649, 22)')+'<div class="le-why">결측치를 지운 1,649행, 22개 속성이에요.</div>'; }
    else if(i===1){ if(!st.df) o[1]=NE('df','준비 셀을 먼저 실행해 데이터를 불러오세요.'); else { st.xy=true; o[1]=OK; } }
    else if(i===2){ if(!st.xy) o[2]=NE('X','X와 y를 먼저 정해야 나눌 수 있어요. 바로 위 셀을 실행하세요.'); else { st.split=true; o[2]=OK; } }
    else if(i===3){ if(!st.split) o[3]=NE('X_train','아직 데이터를 나누지 않았어요.'); else o[3]=OUT('((1319, 20), (1319,), (330, 20), (330,))')+'<div class="le-why">훈련 데이터 1,319행, 테스트 데이터 330행, 속성 20개예요.</div>'; }
    else if(i===4){ st.lr=true; o[4]=OK; }
    else if(i===5){ if(!st.lr) o[5]=NE('linear_reg','모델을 먼저 생성하세요. 바로 위 셀을 실행하세요.'); else if(!st.split) o[5]=NE('X_train','훈련 데이터가 아직 없어요. [5] 셀들을 먼저 실행하세요.'); else { st.fit=true; o[5]=OK+' <span class="muted">→ 훈련 데이터로 학습 완료</span>'; } }
    else if(i===6){ if(!st.fit) o[6]=NE('lin_results','아직 모델을 학습시키지 않았어요.'); else o[6]=OUT(`[-1.31023639e-01  8.05549399e-01 -1.65366218e-02  9.23302716e-02
 -1.26094468e-01  2.58412695e-04 -5.05864100e-03 -1.25064885e-05
  3.46114488e-02 -6.89182089e-02  1.01705848e-02  7.40012348e-02
  1.29221179e-02 -4.31593007e-01  2.94598705e-05 -6.76973582e-10
  1.49973922e-02 -8.43760109e-02  1.13449331e+01  8.60720103e-01]
315.6817315128982`)+'<div class="le-why">가중치 20개(속성마다 하나)와 편향 1개예요. 02 화면에서 속성 이름과 나란히 볼 수 있어요.</div>'; }
    else if(i===7){ if(!st.fit) o[7]=NE('lin_results','아직 모델을 학습시키지 않았어요.'); else { st.pred=true; o[7]=OUT('결정 계수(R^2) =  0.7935432521020239'); } }
    else if(i===8){ if(!st.pred) o[8]=NE('y_pred','결정 계수 셀에서 y_pred(예측값)를 먼저 만들어야 해요.'); else o[8]=OUT(LE_T.slice(0,6).map(t=>`실제 기대 수명: ${t[0].toFixed(3)}, 학습 후 예측 기대 수명: ${t[1].toFixed(3)}, 차이: ${(t[0]-t[1]).toFixed(3)}`).join('\n')); }
    else if(i===9){ if(!st.lr) o[9]=NE('LinearRegression','[6] 1 셀에서 LinearRegression을 먼저 불러오세요.'); else if(!st.split) o[9]=NE('X_train','훈련 데이터가 아직 없어요.'); else o[9]=OUT('LinearRegression()')+'<div class="le-why">교육 기간 하나로 학습했어요. 회귀선은 04 화면의 탐색기에서 볼 수 있어요.</div>'; }
    draw();
  }
  function reset(){ st={df:false,xy:false,split:false,lr:false,fit:false,pred:false,out:CELLS.map(()=>'')}; draw(); }
  function draw(){
    B.innerHTML=CELLS.map((c,i)=>`<div class="le-cell"><div class="le-ct">${c.t}</div><div class="le-cin"><button class="le-run" data-i="${i}" aria-label="${c.t} 실행">▶</button><pre class="le-code">${c.c}</pre></div>${st.out[i]?`<div class="le-cout">${st.out[i]}</div>`:''}</div>`).join('')
      +`<div class="row" style="margin-top:6px"><button class="btn sm ghost" id="csReset">처음부터</button>${st.pred?'<span class="ok">학습과 평가까지 끝났어요. 02·03 화면에서 결과를 살펴봐요.</span>':''}</div>`;
    B.querySelectorAll('.le-run').forEach(b=>b.onclick=()=>run(+b.dataset.i));
    $('csReset').onclick=reset;
  }
  reset();
})();

/* 02 가중치 표 */
(function(){
  $('wTbl').innerHTML='<tr><th>#</th><th class="l">속성</th><th class="l">뜻</th><th>가중치</th><th>부호</th></tr>'+LE_XC.map((c,i)=>{
    const w=LE_W[i], e=w.toExponential(3).replace('e',' × 10^').replace(/\^\+?(-?\d+)/,(m,p)=>'<sup>'+p+'</sup>');
    return `<tr><td>w${i+1}</td><td class="l mono2">${c}</td><td class="l">${LE_KO[c]}</td><td class="num">${e}</td><td><span class="le-sg ${w<0?'neg':'pos'}">${w<0?'−':'+'}</span></td></tr>`;}).join('')
    +`<tr class="y"><td>b</td><td class="l mono2">intercept_</td><td class="l">편향(절편)</td><td class="num">${LE_B.toFixed(4)}</td><td></td></tr>`;
})();

/* 03 예측과 실제 비교판 */
(function(){
  const B=$('pvLab'), n=LE_T.length, o={W:460,H:380,L:44,R:14,T:12,B:40}, v0=35, v1=95;
  const sx=v=>o.L+(v-v0)/(v1-v0)*(o.W-o.L-o.R), sy=v=>o.H-o.B-(v-v0)/(v1-v0)*(o.H-o.T-o.B);
  const order=[...Array(n).keys()].sort((a,b)=>LE_T[a][0]-LE_T[b][0]||a-b);
  const worst=[...Array(n).keys()].reduce((m,k)=>Math.abs(LE_T[k][0]-LE_T[k][1])>Math.abs(LE_T[m][0]-LE_T[m][1])?k:m,0);
  const mae=LE_T.reduce((s,t)=>s+Math.abs(t[0]-t[1]),0)/n;
  let tol=5, sel=0, hl=null;
  const HL={first:[0,1,2,3,4,5],book:[0,1,2,7,8,9]};
  B.innerHTML=`<div class="le-pv"><div><div class="le-svgbox" id="pvBox" tabindex="0" aria-label="예측과 실제 비교판. 왼쪽 오른쪽 방향키로 점을 고릅니다"></div></div>
    <div class="le-pvside"><div class="le-tolh"><label for="pvTol">허용 차이</label><output id="pvTolO">±5년</output></div>
    <div class="le-tol"><button class="btn sm ghost" id="pvMinus" aria-label="허용 차이 줄이기">−</button><input type="range" id="pvTol" min="0.5" max="10" step="0.5" value="5"><button class="btn sm ghost" id="pvPlus" aria-label="허용 차이 늘리기">+</button></div>
    <div class="le-meter"><small>차이가 <span id="pvTolT">±5</span>년 안인 행</small><b id="pvCnt"></b><span>/ 330</span><div class="bar"><i id="pvBar"></i></div></div>
    <div class="le-kv"><span>결정 계수 <b>0.794</b></span><span>차이 절댓값 평균 <b>${mae.toFixed(2)}년</b></span></div>
    <div class="row" style="margin:6px 0"><button class="btn sm ghost" id="pvFirst" aria-pressed="false">처음 6개</button><button class="btn sm ghost" id="pvBook" aria-pressed="false">교과서 6개(1~3, 8~10번째)</button><button class="btn sm ghost" id="pvWorst">가장 크게 빗나간 점</button></div>
    <div class="row" style="margin:0 0 6px"><button class="btn sm ghost" id="pvPrev" aria-label="이전 점">◀ 이전 점</button><button class="btn sm ghost" id="pvNext" aria-label="다음 점">다음 점 ▶</button></div>
    <div class="le-pick" id="pvPick" aria-live="polite"></div></div></div>
    <p class="le-msg" id="pvMsg"></p>`;
  function draw(){
    let g=`<svg viewBox="0 0 ${o.W} ${o.H}" id="pvSvg" role="img" aria-label="실제 기대 수명과 예측 기대 수명 산점도">`;
    for(let v=40;v<=90;v+=10) g+=`<line class="gl" x1="${o.L}" x2="${o.W-o.R}" y1="${sy(v)}" y2="${sy(v)}"/><line class="gl" y1="${o.T}" y2="${o.H-o.B}" x1="${sx(v)}" x2="${sx(v)}"/><text class="tk" x="${o.L-6}" y="${sy(v)+3}" text-anchor="end">${v}</text><text class="tk" x="${sx(v)}" y="${o.H-o.B+14}" text-anchor="middle">${v}</text>`;
    g+=`<polygon points="${sx(v0)},${sy(v0+tol)} ${sx(v1-tol)},${sy(v1)} ${sx(v1)},${sy(v1)} ${sx(v1)},${sy(v1-tol)} ${sx(v0+tol)},${sy(v0)} ${sx(v0)},${sy(v0)}" fill="#1f9d74" opacity=".12"/>`;
    g+=`<line x1="${sx(v0)}" y1="${sy(v0)}" x2="${sx(v1)}" y2="${sy(v1)}" stroke="#16202c" stroke-width="1.5" stroke-dasharray="5 4"/>`;
    let c=0;
    const mark=hl?HL[hl]:[];
    LE_T.forEach((t,k)=>{ const inn=Math.abs(t[0]-t[1])<=tol; if(inn) c++; const h=mark.includes(k);
      g+=`<circle cx="${sx(t[0])}" cy="${sy(t[1])}" r="${h?5:3}" fill="${inn?'#1f9d74':'#d64535'}" opacity="${h?1:.6}" ${h?'stroke="#16202c" stroke-width="1.5"':''}/>`; });
    const s=LE_T[sel];
    g+=`<line x1="${sx(s[0])}" y1="${sy(s[0])}" x2="${sx(s[0])}" y2="${sy(s[1])}" stroke="#c98a00" stroke-width="2"/><circle cx="${sx(s[0])}" cy="${sy(s[1])}" r="7" fill="none" stroke="#c98a00" stroke-width="3"/>`;
    g+=`<text class="axl" x="${(o.L+o.W-o.R)/2}" y="${o.H-6}" text-anchor="middle">실제 기대 수명(세)</text><text class="axl" x="12" y="${(o.T+o.H-o.B)/2}" transform="rotate(-90 12 ${(o.T+o.H-o.B)/2})" text-anchor="middle">예측 기대 수명(세)</text><text class="tk" x="${sx(88)}" y="${sy(91)}" text-anchor="end">대각선 = 정확히 맞힘</text></svg>`;
    $('pvBox').innerHTML=g;
    $('pvCnt').textContent=c; $('pvBar').style.width=(c/n*100)+'%';
    $('pvTolO').textContent='±'+tol+'년'; $('pvTolT').textContent='±'+tol;
    const d=s[0]-s[1];
    $('pvPick').innerHTML=`<b>${LE_CNK[s[2]]}</b> <span class="muted">(${LE_CN[s[2]]})</span> <b>${s[3]}</b> · 테스트 데이터 ${sel+1}번째 행<br>실제 <b>${s[0].toFixed(1)}</b>세 · 예측 <b>${s[1].toFixed(1)}</b>세 · 차이 <b class="${Math.abs(d)<=tol?'ok':'ng'}">${d>0?'+':''}${d.toFixed(2)}</b>${d<0?' (실제보다 높게 예측)':' (실제보다 낮게 예측)'}`;
    $('pvMsg').innerHTML=`±${tol}년 안을 「맞힘」으로 보면 330개 중 <b>${c}개(${(c/n*100).toFixed(1)}%)</b>를 맞힌 셈이에요. ${tol<=1?'기준을 엄격하게 잡으면 맞힌 비율이 크게 줄어요. ':''}${tol>=8?'기준을 느슨하게 잡으면 거의 다 맞힌 것처럼 보여요. ':''}${hl==='book'?'교과서에 실린 6개(1~3, 8~10번째)는 차이가 모두 5년 안이지만, <b>처음 6개</b>에는 6~7년 차이가 나는 행이 2개 있어요. ':''}${hl==='first'?'처음 6개 중 2개(5·6번째)는 차이가 6년을 넘어요. ':''}이렇게 숫자를 예측하는 모델은 <b>기준을 어떻게 잡느냐</b>에 따라 「정확도」가 달라지므로, <b>결정 계수</b>나 <b>차이(오차)의 크기</b>로 평가해요.`;
  }
  const setTol=v=>{ tol=Math.max(0.5,Math.min(10,v)); $('pvTol').value=tol; draw(); };
  $('pvTol').oninput=e=>setTol(+e.target.value);
  $('pvMinus').onclick=()=>setTol(tol-0.5); $('pvPlus').onclick=()=>setTol(tol+0.5);
  const setHl=k=>{ hl=hl===k?null:k; ['first','book'].forEach(x=>{ const b=$(x==='first'?'pvFirst':'pvBook'); b.classList.toggle('on',hl===x); b.setAttribute('aria-pressed',hl===x?'true':'false'); }); if(hl) sel=HL[hl][0]; draw(); };
  $('pvFirst').onclick=()=>setHl('first'); $('pvBook').onclick=()=>setHl('book');
  $('pvWorst').onclick=()=>{ sel=worst; draw(); };
  const step=dlt=>{ const p=order.indexOf(sel), q=Math.max(0,Math.min(n-1,p+dlt)); sel=order[q]; draw(); };
  $('pvPrev').onclick=()=>step(-1); $('pvNext').onclick=()=>step(1);
  const box=$('pvBox');
  box.addEventListener('click',e=>{ const svg=$('pvSvg'); const r=svg.getBoundingClientRect(); if(!r.width) return;
    const x=(e.clientX-r.left)/r.width*o.W, y=(e.clientY-r.top)/r.height*o.H; let best=-1, bd=1e9;
    LE_T.forEach((t,k)=>{ const dd=(sx(t[0])-x)**2+(sy(t[1])-y)**2; if(dd<bd){bd=dd; best=k;} }); if(best>=0&&bd<900){ sel=best; draw(); } });
  box.addEventListener('keydown',e=>{ if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight') return; e.preventDefault(); step(e.key==='ArrowRight'?1:-1); });
  draw();
})();

/* 04 회귀선 탐색기 */
(function(){
  const B=$('rlLab'), Yi=LE_A.length;
  const UNIT={'Schooling':['교육 기간이 1년 더 긴','1'],'Income composition of resources':['소득 지수가 0.1 더 높은','0.1'],'Adult Mortality':['성인 사망률(1,000명당)이 100 더 높은','100'],'HIV/AIDS':['HIV/AIDS 사망 수(1,000명당)가 1 더 많은','1'],'BMI':['평균 체질량 지수가 1 더 높은','1'],'GDP':['1인당 GDP가 1,000달러 더 많은','1000']};
  let a=0, mask=1;
  const nice=v=>Math.abs(v)>=1e4?Math.round(v/1e3)+'k':Math.abs(v)>=100?Math.round(v):(Math.round(v*100)/100);
  B.innerHTML=`<div class="le-rlb" id="rlBtns" role="group" aria-label="회귀선에 쓸 속성">${LE_A.map((c,i)=>`<button class="btn sm ghost" data-i="${i}" aria-pressed="false">${sname(c)}</button>`).join('')}</div>
    <div class="le-rl"><div id="rlPlot" class="le-svgbox"></div><div class="le-rlinfo" id="rlInfo"></div></div>
    <div class="le-cmb"><h4>여러 속성 함께 쓰기 <small class="muted">(눌러서 켜고 끄기)</small></h4><div class="le-rlb" id="cbBtns">${LE_A.map((c,i)=>`<button class="le-tg" data-i="${i}" aria-pressed="false">${sname(c)}</button>`).join('')}</div>
    <div id="cbOut"></div></div>`;
  function plot(){
    const c=LE_A[a], xs=LE_TR.map(r=>r[a]), x0=Math.min(...xs), x1=Math.max(...xs), y0=40, y1=90, o={W:460,H:300,L:44,R:14,T:12,B:40};
    const sx=v=>o.L+(v-x0)/(x1-x0)*(o.W-o.L-o.R), sy=v=>o.H-o.B-(v-y0)/(y1-y0)*(o.H-o.T-o.B);
    const [m,b,r2]=LE_SG[c];
    let g=`<svg viewBox="0 0 ${o.W} ${o.H}" role="img" aria-label="${c}와 기대 수명 산점도와 회귀선"><defs><clipPath id="rlClip"><rect x="${o.L}" y="${o.T}" width="${o.W-o.L-o.R}" height="${o.H-o.T-o.B}"/></clipPath></defs>`;
    for(let v=40;v<=90;v+=10) g+=`<line class="gl" x1="${o.L}" x2="${o.W-o.R}" y1="${sy(v)}" y2="${sy(v)}"/><text class="tk" x="${o.L-6}" y="${sy(v)+3}" text-anchor="end">${v}</text>`;
    for(let t=0;t<=4;t++){ const v=x0+(x1-x0)*t/4; g+=`<text class="tk" x="${sx(v)}" y="${o.H-o.B+14}" text-anchor="middle">${nice(v)}</text>`; }
    g+='<g clip-path="url(#rlClip)">';
    LE_TR.forEach(r=>{ g+=`<circle cx="${sx(r[a])}" cy="${sy(r[Yi])}" r="2.2" fill="#2f6fd0" opacity=".35"/>`; });
    g+=`<line x1="${sx(x0)}" y1="${sy(m*x0+b)}" x2="${sx(x1)}" y2="${sy(m*x1+b)}" stroke="#d64535" stroke-width="3"/></g>`;
    g+=`<text class="axl" x="${(o.L+o.W-o.R)/2}" y="${o.H-6}" text-anchor="middle">${sname(c)} (${LE_KO2[c]||LE_KO[c]})</text><text class="axl" x="12" y="${(o.T+o.H-o.B)/2}" transform="rotate(-90 12 ${(o.T+o.H-o.B)/2})" text-anchor="middle">기대 수명(세)</text></svg>`;
    $('rlPlot').innerHTML=g;
    const u=UNIT[c], eff=m*(+u[1]);
    $('rlInfo').innerHTML=`<div class="le-eq">예측 기대 수명 = <b>${m.toPrecision(4)}</b> × ${sname(c)} + <b>${b.toFixed(2)}</b></div>
      <p>기울기의 뜻: ${u[0]} 나라는 예측 기대 수명이 약 <b>${Math.abs(eff).toFixed(2)}세 ${eff<0?'낮아요':'높아요'}</b>. (원인이 아니라 데이터의 경향이에요)</p>
      <div class="le-meter"><small>테스트 데이터 결정 계수 (속성 1개)</small><b>${r2.toFixed(3)}</b><div class="bar"><i style="width:${Math.max(0,r2)*100}%"></i></div></div>
      <div class="le-meter all"><small>속성 20개를 모두 쓴 모델</small><b>${LE_ALL.toFixed(3)}</b><div class="bar"><i style="width:${LE_ALL*100}%"></i></div></div>
      <p class="note">${c==='GDP'?'GDP는 오른쪽 끝에 아주 큰 값이 있어 직선이 데이터를 잘 따라가지 못해요. 이런 이상치 같은 값은 예측을 부정확하게 만들 수 있어요.':c==='Schooling'?'교과서 200쪽과 같은 회귀선이에요. 교육 기간이 긴 나라일수록 기대 수명이 높은 경향을 기울기로 읽을 수 있어요.':'점들이 직선 주변에 얼마나 모여 있는지 보면 결정 계수를 짐작할 수 있어요.'}</p>`;
    B.querySelectorAll('#rlBtns button').forEach(x=>{ const on=+x.dataset.i===a; x.classList.toggle('on',on); x.setAttribute('aria-pressed',on?'true':'false'); });
  }
  function combo(){
    B.querySelectorAll('#cbBtns .le-tg').forEach(x=>{ const on=mask>>+x.dataset.i&1; x.classList.toggle('on',!!on); x.setAttribute('aria-pressed',on?'true':'false'); });
    const names=LE_A.filter((_,i)=>mask>>i&1).map(sname);
    const r=mask?LE_CB[mask]:null;
    $('cbOut').innerHTML=mask?`<div class="le-meter"><small>고른 속성 ${names.length}개: ${names.join(', ')}</small><b>${r.toFixed(3)}</b><div class="bar"><i style="width:${r*100}%"></i></div></div>
      <div class="le-meter all"><small>속성 20개 모두</small><b>${LE_ALL.toFixed(3)}</b><div class="bar"><i style="width:${LE_ALL*100}%"></i></div></div>
      <p class="le-msg">${names.length===1?'속성을 하나 더 켜 보세요. 결정 계수가 얼마나 오르나요?':r>=LE_ALL-0.02?`속성 <b>${names.length}개</b>로도 20개를 모두 쓴 모델(${LE_ALL.toFixed(3)})과 거의 비슷해요. 꼭 필요한 속성을 고르는 것도 성능 개선이에요.`:`20개 모두 쓴 모델보다 <b>${(LE_ALL-r).toFixed(3)}</b> 낮아요. 어떤 속성을 더하면 가장 많이 오를까요?`}</p>`
      :'<p class="le-msg">속성을 하나 이상 켜 주세요.</p>';
  }
  B.querySelectorAll('#rlBtns button').forEach(x=>x.onclick=()=>{ a=+x.dataset.i; plot(); });
  B.querySelectorAll('#cbBtns .le-tg').forEach(x=>x.onclick=()=>{ mask^=1<<+x.dataset.i; combo(); });
  plot(); combo();
})();

